from pathlib import Path

src = Path('eio26/EioClient.java')
s = src.read_text()

if 'public static final String VERSION = "0.26.1";' not in s:
    def rep(old, new, label, count=1):
        global s
        if old not in s:
            raise SystemExit('patch target not found: ' + label)
        s = s.replace(old, new, count)

    rep('public static final String VERSION = "0.26.0";', 'public static final String VERSION = "0.26.1";', 'version')
    rep('public static final String BUILD_ID = "EIO-026-AREA2";', 'public static final String BUILD_ID = "EIO-0261-MINEFIX1";', 'build id')

    rep('''    private static boolean areaMoveRequested;\n    private static boolean areaComplete;\n    private static final Set<BlockPos> AREA_MINE_SKIPPED = new HashSet<>();''', '''    private static boolean areaMoveRequested;\n    private static boolean areaComplete;\n    private static BlockPos areaDestroyTarget;\n    private static boolean areaDestroyStarted;\n    private static int areaMineWorkTicks;\n    private static final Set<BlockPos> AREA_MINE_SKIPPED = new HashSet<>();''', 'area destroy state')

    rep('''.num("Aim Timeout", 14.0, 4.0, 50.0, 1.0, "Ticks allowed to line up with a target before temporarily skipping it.")\n                .num("Move Timeout", 100.0, 20.0, 240.0, 5.0, "Ticks allowed to reach one navigation cell before moving to the next cell.")''', '''.num("Aim Timeout", 14.0, 4.0, 50.0, 1.0, "Ticks allowed to line up with a target before temporarily skipping it.")\n                .num("Mine Timeout", 240.0, 40.0, 600.0, 20.0, "Maximum ticks to work one block before skipping it and continuing the lane.")\n                .num("Move Timeout", 100.0, 20.0, 240.0, 5.0, "Ticks allowed to reach one navigation cell before moving to the next cell.")''', 'mine timeout setting')

    old = '''                    if (areaMineTarget != null && mc.level.getBlockState(areaMineTarget).isAir()) {\n                        areaMinedThisPass++;\n                        areaMineTarget = null;\n                        areaMineAimTicks = 0;\n                        areaMineRearmTicks = Math.max(1, (int) Math.round(areaMiner.num("Retarget Delay").value));\n                    } else if (areaMineTarget != null && !validAreaMineTarget(mc, areaMiner, areaMineTarget)) {\n                        AREA_MINE_SKIPPED.add(areaMineTarget.immutable());\n                        areaMineTarget = null;\n                        areaMineAimTicks = 0;\n                        areaMineRearmTicks = Math.max(1, (int) Math.round(areaMiner.num("Retarget Delay").value));\n                    }\n                    if (areaMineRearmTicks > 0) {\n                        areaMineRearmTicks--;\n                    } else {\n                        if (areaMineTarget == null) {\n                            areaMineTarget = findAreaMineTarget(mc, areaMiner);\n                            areaMineAimTicks = 0;\n                            if (areaMineTarget == null && !AREA_MINE_SKIPPED.isEmpty()) {\n                                AREA_MINE_SKIPPED.clear();\n                                areaMineTarget = findAreaMineTarget(mc, areaMiner);\n                            }\n                        }\n                        if (areaMineTarget != null) {\n                            if (areaMiner.bool("Face Block").value) faceBlock(mc.player, areaMineTarget);\n                            boolean aimed = mc.hitResult instanceof BlockHitResult hit && hit.getBlockPos().equals(areaMineTarget);\n                            if (aimed) {\n                                shouldForceAttack = true;\n                                areaMineAimTicks = 0;\n                            } else if (++areaMineAimTicks >= Math.max(4, (int) Math.round(areaMiner.num("Aim Timeout").value))) {\n                                AREA_MINE_SKIPPED.add(areaMineTarget.immutable());\n                                areaMineTarget = null;\n                                areaMineAimTicks = 0;\n                                areaMineRearmTicks = 1;\n                            }\n                        }\n                    }'''

    new = '''                    if (areaMineTarget != null && mc.level.getBlockState(areaMineTarget).isAir()) {\n                        areaMinedThisPass++;\n                        stopAreaDestroy(mc);\n                        areaMineTarget = null;\n                        areaMineAimTicks = 0;\n                        areaMineWorkTicks = 0;\n                        areaMineRearmTicks = Math.max(1, (int) Math.round(areaMiner.num("Retarget Delay").value));\n                    } else if (areaMineTarget != null && !validAreaMineTarget(mc, areaMiner, areaMineTarget)) {\n                        stopAreaDestroy(mc);\n                        AREA_MINE_SKIPPED.add(areaMineTarget.immutable());\n                        areaMineTarget = null;\n                        areaMineAimTicks = 0;\n                        areaMineWorkTicks = 0;\n                        areaMineRearmTicks = Math.max(1, (int) Math.round(areaMiner.num("Retarget Delay").value));\n                    }\n                    if (areaMineRearmTicks > 0) {\n                        areaMineRearmTicks--;\n                    } else {\n                        if (areaMineTarget == null) {\n                            areaMineTarget = findAreaMineTarget(mc, areaMiner);\n                            areaMineAimTicks = 0;\n                            areaMineWorkTicks = 0;\n                            if (areaMineTarget == null && !AREA_MINE_SKIPPED.isEmpty()) {\n                                AREA_MINE_SKIPPED.clear();\n                                areaMineTarget = findAreaMineTarget(mc, areaMiner);\n                            }\n                        }\n                        if (areaMineTarget != null) {\n                            if (areaMiner.bool("Face Block").value) faceBlock(mc.player, areaMineTarget);\n                            areaMineAimTicks++;\n                            areaMineWorkTicks++;\n                            // The old implementation only held the key at END_CLIENT_TICK. That can miss\n                            // Minecraft's destroy-start window even though navigation still works. Drive\n                            // the normal MultiPlayerGameMode start/continue path instead.\n                            if (areaMineAimTicks >= 2) continueAreaDestroy(mc, areaMineTarget);\n                            if (areaMineWorkTicks >= Math.max(40, (int) Math.round(areaMiner.num("Mine Timeout").value))) {\n                                stopAreaDestroy(mc);\n                                AREA_MINE_SKIPPED.add(areaMineTarget.immutable());\n                                areaMineTarget = null;\n                                areaMineAimTicks = 0;\n                                areaMineWorkTicks = 0;\n                                areaMineRearmTicks = Math.max(1, (int) Math.round(areaMiner.num("Retarget Delay").value));\n                            }\n                        }\n                    }'''
    rep(old, new, 'area mining tick loop')

    rep('''    private static void resetAreaRuntime() {\n        areaMineTarget = null;\n        areaMineRearmTicks = 0;\n        areaMineAimTicks = 0;''', '''    private static void resetAreaRuntime() {\n        areaMineTarget = null;\n        areaDestroyTarget = null;\n        areaDestroyStarted = false;\n        areaMineWorkTicks = 0;\n        areaMineRearmTicks = 0;\n        areaMineAimTicks = 0;''', 'area reset state')

    anchor = '''    private static boolean validAreaMineTarget(Minecraft mc, Mod area, BlockPos pos) {'''
    helper = '''    private static Direction areaMiningFace(Player player, BlockPos pos) {\n        double dx = player.getX() - (pos.getX() + 0.5);\n        double dy = player.getEyeY() - (pos.getY() + 0.5);\n        double dz = player.getZ() - (pos.getZ() + 0.5);\n        double ax = Math.abs(dx), ay = Math.abs(dy), az = Math.abs(dz);\n        if (ay >= ax && ay >= az) return dy >= 0.0 ? Direction.UP : Direction.DOWN;\n        if (ax >= az) return dx >= 0.0 ? Direction.EAST : Direction.WEST;\n        return dz >= 0.0 ? Direction.SOUTH : Direction.NORTH;\n    }\n\n    private static void continueAreaDestroy(Minecraft mc, BlockPos pos) {\n        if (mc.player == null || mc.gameMode == null || pos == null || !withinVanillaBlockRange(mc, pos)) return;\n        Direction face = areaMiningFace(mc.player, pos);\n        if (mc.hitResult instanceof BlockHitResult hit && hit.getBlockPos().equals(pos)) face = hit.getDirection();\n        if (!areaDestroyStarted || areaDestroyTarget == null || !areaDestroyTarget.equals(pos)) {\n            if (areaDestroyStarted) mc.gameMode.stopDestroyBlock();\n            areaDestroyTarget = pos.immutable();\n            areaDestroyStarted = mc.gameMode.startDestroyBlock(areaDestroyTarget, face);\n        }\n        if (areaDestroyStarted) {\n            if (mc.gameMode.continueDestroyBlock(areaDestroyTarget, face)) mc.player.swing(InteractionHand.MAIN_HAND);\n        }\n    }\n\n    private static void stopAreaDestroy(Minecraft mc) {\n        if (areaDestroyStarted && mc != null && mc.gameMode != null) mc.gameMode.stopDestroyBlock();\n        areaDestroyStarted = false;\n        areaDestroyTarget = null;\n    }\n\n''' + anchor
    rep(anchor, helper, 'area destroy helpers')

    # Clear direct destroy state when mining is blocked/paused.
    rep('''        } else {\n            areaMineTarget = null;\n            areaMineRearmTicks = 0;\n            areaMineAimTicks = 0;\n            areaMoveRequested = false;''', '''        } else {\n            stopAreaDestroy(mc);\n            areaMineTarget = null;\n            areaMineRearmTicks = 0;\n            areaMineAimTicks = 0;\n            areaMineWorkTicks = 0;\n            areaMoveRequested = false;''', 'mining blocked cleanup')

    src.write_text(s)

props = Path('gradle.properties')
p = props.read_text()
if 'mod_version=0.26.0+26.3' in p:
    p = p.replace('mod_version=0.26.0+26.3', 'mod_version=0.26.1+26.3', 1)
elif 'mod_version=0.26.1+26.3' not in p:
    raise SystemExit('unexpected mod_version')
props.write_text(p)
